<script setup lang="ts">
/**
 * Demo: SnVideoPlayer — basic playback with the full control bar.
 *
 * Self-contained media (data URI, Web Platform Tests sample, BSD-3-Clause)
 * so the demo needs no network. Keyboard shortcuts are active once the
 * player is focused: Space/K play-pause, ←→ seek ±5s, ↑↓ volume,
 * M mute, F fullscreen.
 */
import { ref } from 'vue';
import { SnVideoPlayer } from '@snui/vue-web';

const videoSrc =
  'data:video/mp4;base64,';

const poster =
  'data:image/svg+xml;charset=utf-8,' +
  encodeURIComponent(
    `<svg xmlns="http://www.w3.org/2000/svg" width="640" height="360"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#69b1ff"/><stop offset="1" stop-color="#0958d9"/></linearGradient></defs><rect width="640" height="360" fill="url(#g)"/><circle cx="500" cy="94" r="94" fill="rgba(255,255,255,0.16)"/><text x="50%" y="52%" fill="rgba(255,255,255,0.92)" font-family="system-ui,sans-serif" font-size="36" font-weight="600" text-anchor="middle" dominant-baseline="middle">宣传片</text></svg>`,
  );

const lastEvent = ref('');
function note(name: string): () => void {
  return () => {
    lastEvent.value = name;
  };
}
</script>

<template>
  <div class="demo-stack">
    <SnVideoPlayer
      :src="videoSrc"
      :poster="poster"
      title="宣传片"
      @play="note('play')"
      @pause="note('pause')"
      @ended="note('ended')"
      @error="note('error')"
      @fullscreen-change="note('fullscreen-change')"
    />
    <p class="demo-hint">
      聚焦播放器后可用键盘：Space 播放/暂停 · ←→ 快进退 5s · ↑↓ 音量 · M 静音 · F 全屏
      <template v-if="lastEvent">　—　最近事件：<code>{{ lastEvent }}</code></template>
    </p>
  </div>
</template>

<style scoped>
.demo-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.demo-hint {
  margin: 0;
  color: var(--sn-web-color-text-secondary, #666);
  font-size: 12px;
}
</style>
